  ],
  "safety_limits": [
    {
      "limit_id": "L01",
      "text": "若活动中出现胸痛、晕厥或接近晕厥、异常严重的呼吸困难等急性警示信号，应立即停止运动并寻求紧急医疗帮助。",
      "severity": "critical"
    },
